<?php declare(strict_types=1);$positionText??=static fn(string $source,array $values=[]):string=>strtr($source,array_combine(array_map(static fn($key)=>'{'.$key.'}',array_keys($values)),array_values($values))); ?>
<details class="card accounting-help"><summary><?= e($positionText('Was bedeuten Sphäre, Steuerkonto und BU-Schlüssel?')) ?></summary>
<p><strong><?= e($positionText('Sphäre = Vereinsbereich:')) ?></strong> <?= e($positionText('Sie beschreibt, für welchen Teil der Vereinsarbeit ein Betrag bestimmt ist.')) ?></p>
<ul><li><strong><?= e($positionText('1 · Ideeller Bereich:')) ?></strong> <?= e($positionText('Gemeinsame Vereinsarbeit ohne Verkauf einer Leistung, zum Beispiel echte Mitgliedsbeiträge und Spenden.')) ?></li><li><strong><?= e($positionText('2 · Vermögensverwaltung:')) ?></strong> <?= e($positionText('Zum Beispiel Zinsen oder eine längerfristige Vermietung; die konkrete Tätigkeit entscheidet.')) ?></li><li><strong><?= e($positionText('3 · Zweckbetrieb:')) ?></strong> <?= e($positionText('Wirtschaftliche Tätigkeit, die unter den steuerlichen Voraussetzungen unmittelbar dem gemeinnützigen Zweck dient. Eine Kulturveranstaltung ist nicht allein wegen ihres Namens automatisch ein Zweckbetrieb.')) ?></li><li><strong><?= e($positionText('4 · Wirtschaftlicher Geschäftsbetrieb:')) ?></strong> <?= e($positionText('Wirtschaftliche Tätigkeit außerhalb eines Zweckbetriebs, zum Beispiel gesonderte Werbung für einen Sponsor.')) ?></li><li><strong><?= e($positionText('9 · Sammelposten:')) ?></strong> <?= e($positionText('Noch zu klärende oder die Gesamtkörperschaft betreffende Positionen. Eine steuerliche Aufteilung muss vor dem endgültigen Abschluss bestätigt werden.')) ?></li></ul>
<p><strong><?= e($positionText('Steuerkonto = Buchhaltungskonto:')) ?></strong> <?= e($positionText('Diese Nummer beschreibt die Art des Betrags. Es ist keine IBAN und kein weiteres Bankkonto. Für eine echte Geldspende mit Zuwendungsbestätigung ist im Kontenplan zum Beispiel')) ?> <strong>40450</strong> <?= e($positionText('vorgesehen; für eine Sachspende mit Bestätigung')) ?> <strong>40550</strong><?= e($positionText('. Verwenden Sie das zum tatsächlichen Vorgang passende Konto.')) ?></p>
<p><strong><?= e($positionText('BU-Schlüssel = Buchungsschlüssel:')) ?></strong> <?= e($positionText('Ein zusätzlicher Hinweis für die Umsatzsteuerbehandlung im DATEV-Export. Bei echten Spenden und Mitgliedsbeiträgen bleibt er leer. Ohne Vorsteuerabzugsberechtigung darf ein Einkaufsbeleg nicht allein wegen ausgewiesener Umsatzsteuer einen Vorsteuerschlüssel erhalten. Die Preise werden hier brutto erfasst; die Steuerangabe laut Original begründet keinen Vorsteuerabzug.')) ?></p>
<p><strong><?= e($positionText('Wenn Sie unsicher sind:')) ?></strong> <?= e($positionText('Lassen Sie unklare Angaben offen. Eine bekannte Sphäre kann bereits gewählt werden, auch wenn das Steuerkonto noch offen bleibt und klären Sie die Zuordnung mit dem Kassenwart. Die Exportprüfung zeigt offene Kontierungen. Ein Konto oder eine Sphäre wird nicht geraten.')) ?></p>
<p><strong><?= e($positionText('Umfang:')) ?></strong> <?= e($positionText('Hinterlegt ist der SKR42-Katalog für 2026 mit vier steuerlichen Vereinsbereichen und dem Sammelposten. Das Suchfeld bietet alle freigegebenen Konten des hinterlegten Katalogs an. Über')) ?> <strong><?= e($positionText('Steuerkontenliste anzeigen')) ?></strong> <?= e($positionText('können Sie zusätzlich nach Kategorien suchen. Reservierte oder widersprüchliche Quellkonten bleiben gesperrt. Eigene Unterkonten können ergänzt werden. Für Buchungen werden acht geprüfte inländische BU-Schlüssel unterstützt, nicht alle Sonderfälle aus der vollständigen Referenzliste.')) ?></p>
<p><strong><?= e($positionText('Ältere Rechnungen:')) ?></strong> <?= e($positionText('Das Rechnungsjahr folgt automatisch dem Rechnungsdatum. Der vorhandene Kontenplan dient auch für die interne Zuordnung älterer Rechnungen; seine Version bleibt dabei 2026. Die Jahreszahl des Kontenplans ändert das Rechnungsdatum nicht. Historische DATEV-Exportjahre sind damit noch nicht freigeschaltet.')) ?></p>
<p><strong><?= e($positionText('Und bei Gegenständen?')) ?></strong> <?= e($positionText('Die steuerliche Kontierung steht an der zugehörigen Rechnung oder Sachspende. Im Inventar werden Bestand, Seriennummern und dokumentierte Werte geführt. Eine Verknüpfung erzeugt keine zweite Buchung. Anlagevermögen, Sofortaufwand und gegebenenfalls Abschreibungen müssen passend zur Anschaffung beurteilt werden; die Inventarzuordnung entscheidet das nicht automatisch.')) ?></p>
</details>

<p><?= e($positionText('Im DATEV-Buchungssatz wird die genaue Zuordnung im Feld')) ?> <strong><?= e($positionText('KOST1')) ?></strong> <?= e($positionText('gespeichert. Optional: 11–19 für Unterteilungen des ideellen Bereichs, 21–29 für Vermögensverwaltung, 31–39 für Zweckbetriebe und 41–49 für wirtschaftliche Geschäftsbetriebe. Die Hauptsphäre bleibt in den Summen erhalten.')) ?></p>
